import { copyFileSync, existsSync, mkdirSync, readdirSync } from 'node:fs';
import { homedir } from 'node:os';
import { basename, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { nowIso, readJSON, writeJSON, writeText } from './util.mjs';

export const KIT_ROOT = fileURLToPath(new URL('..', import.meta.url));
export const TEMPLATES = join(KIT_ROOT, 'templates');

/**
 * Per-project store, `<root>/.qa-kit/`:
 *
 *   config.json          conventions the scanner detected or the team set (committed)
 *   memory/*.md          curated knowledge: app, conventions, glossary (committed)
 *   memory/lessons.jsonl atomic facts and lessons, append-mostly (committed)
 *   index/               regenerated by `scan` / `index` (ignored)
 *   history/             test run history and per-test stability (ignored)
 */
export function storePaths(root) {
	const dir = process.env.QA_KIT_DIR || join(root, '.qa-kit');
	return {
		dir,
		config: join(dir, 'config.json'),
		memoryDir: join(dir, 'memory'),
		lessons: join(dir, 'memory', 'lessons.jsonl'),
		indexDir: join(dir, 'index'),
		structure: join(dir, 'index', 'structure.json'),
		cases: join(dir, 'index', 'test-cases.json'),
		historyDir: join(dir, 'history'),
		runs: join(dir, 'history', 'runs.jsonl'),
		tests: join(dir, 'history', 'tests.json'),
		ingestState: join(dir, 'history', 'ingest-state.json'),
		lastReport: join(dir, 'history', 'last-report.json')
	};
}

export function hasStore(root) {
	return existsSync(storePaths(root).dir);
}

export const DEFAULT_CONFIG = {
	version: 2,
	// Everything below is detected by `scan` when empty and can be edited by hand
	// (`qa-kit config set <path> <value>`). Nothing here is specific to one project.
	app: { name: null, description: null },
	e2e: {
		testDir: null,
		configFile: null,
		outputDir: null,
		htmlReportDir: null,
		// Module that specs import `test`/`expect` from (a custom fixtures file or @playwright/test).
		fixturesImport: null,
		// Package script that runs Playwright for the whole suite.
		runScript: null,
		// Playwright project names; needed when the config computes them in code.
		projects: [],
		// Folder → project/script, so a run for a path picks the right project:
		// [{ "path": "e2e/admin", "project": "admin", "script": "test:e2e:admin" }]
		scopes: [],
		// Tags that mark tests which create/change/delete data.
		mutationTags: [],
		// Env vars that unlock risky behaviour; agents must never set them.
		protectedEnv: []
	},
	catalog: {
		// File names of human test-case catalogs; null = detect, falling back to newFileName.
		fileNames: null,
		newFileName: 'test-cases.md',
		idPattern: '[A-Z][A-Z0-9]{1,9}[-_]\\d{2,4}',
		// Language packs used to read catalogs (lib/vocab.mjs); null = all packs.
		languages: null,
		// Extra words, same shape as a pack: { "todo": ["nog niet"], "columns": { "steps": ["stappen"] } }
		vocabulary: {}
	},
	language: null,
	rules: []
};

export function loadConfig(root) {
	const saved = readJSON(storePaths(root).config, {});
	const legacy = saved.e2e ?? {};
	return {
		...DEFAULT_CONFIG,
		...saved,
		app: { ...DEFAULT_CONFIG.app, ...(saved.app ?? {}) },
		e2e: Object.fromEntries(Object.entries({ ...DEFAULT_CONFIG.e2e, ...legacy }).filter(([k]) => k !== 'catalogFileNames' && k !== 'caseIdPattern')),
		catalog: {
			...DEFAULT_CONFIG.catalog,
			// v1 kept these under e2e.
			...(legacy.catalogFileNames ? { fileNames: legacy.catalogFileNames } : {}),
			...(legacy.caseIdPattern ? { idPattern: legacy.caseIdPattern } : {}),
			...(saved.catalog ?? {})
		}
	};
}

export function saveConfig(root, config) {
	writeJSON(storePaths(root).config, config);
}

/** Creates the store and seeds memory files from templates without overwriting. */
export function ensureStore(root) {
	const p = storePaths(root);
	for (const d of [p.dir, p.memoryDir, p.indexDir, p.historyDir]) mkdirSync(d, { recursive: true });

	const gitignore = join(p.dir, '.gitignore');
	if (!existsSync(gitignore)) {
		writeText(
			gitignore,
			'# Regenerated by `qa-kit scan` / `qa-kit index`\nindex/\n# Local run history; share lessons through memory/ instead\nhistory/\n'
		);
	}
	if (!existsSync(p.config)) saveConfig(root, DEFAULT_CONFIG);

	const memTemplates = join(TEMPLATES, 'memory');
	for (const name of readdirSync(memTemplates)) {
		const target = join(p.memoryDir, basename(name));
		if (!existsSync(target)) copyFileSync(join(memTemplates, name), target);
	}
	if (!existsSync(p.lessons)) writeText(p.lessons, '');
	return p;
}

/**
 * User-level store shared by every app: lessons that hold across projects (Playwright,
 * tooling, team habits) and the list of apps that use qa-kit.
 */
export function globalPaths() {
	const dir = process.env.QA_KIT_HOME || join(homedir(), '.qa-kit');
	return { dir, lessons: join(dir, 'lessons.jsonl'), apps: join(dir, 'apps.json') };
}

export function registerApp(root, info = {}) {
	const g = globalPaths();
	const apps = readJSON(g.apps, {});
	apps[root] = { ...(apps[root] ?? {}), ...info, root, lastSeenAt: nowIso() };
	writeJSON(g.apps, apps);
	return apps[root];
}

export function listApps() {
	return Object.values(readJSON(globalPaths().apps, {})).sort((a, b) => (b.lastSeenAt ?? '').localeCompare(a.lastSeenAt ?? ''));
}
